#!/usr/bin/env python3
from pwn import *
import itertools

# Configure logging
context.log_level = 'error'

def test_flag(flag_content):
    # Run the binary with the test flag
    p = process('/home/ctfplayer/ctf_files/counting')
    p.sendline(flag_content.encode())

    try:
        output = p.recvall(timeout=2).decode()
        p.close()
        return output
    except:
        p.close()
        return ""

def validate_constraints(content):
    # Check if content satisfies bitwise AND with 0xffffffd4
    for c in content:
        if (ord(c) & 0xffffffd4) != 0:
            return False
    return True

def generate_test_flags():
    # Generate different patterns for testing
    base_format = "flag{%s}"
    content_length = 17 - 5  # Total length minus flag{}

    # Test ascending sequences
    for start in range(0, 100):
        content = ""
        for i in range(start, start + content_length):
            if i % 35 == 0 or i % 46 == 0:
                content += str(i % 10)
            if len(content) == content_length:
                flag = base_format % content
                if validate_constraints(flag):
                    yield flag

    # Test specific multiples of 0x30
    for i in range(1, 100):
        num = i * 0x30
        if num > 999999999999:
            break
        content = str(num).zfill(content_length)
        flag = base_format % content
        if validate_constraints(flag):
            yield flag

    # Test values around 0x1a6
    base = 0x1a6
    for offset in range(-50, 51):
        num = base + offset
        content = str(num).zfill(content_length)
        flag = base_format % content
        if validate_constraints(flag):
            yield flag

def main():
    print("Starting flag testing...")

    interesting_responses = set()
    for test_flag in generate_test_flags():
        result = test_flag(test_flag)
        if "Invalid" not in result and result.strip():
            print(f"Interesting response for {test_flag}:")
            print(result)
            interesting_responses.add((test_flag, result))

    print("\nSummary of interesting responses:")
    for flag, response in interesting_responses:
        print(f"{flag}: {response}")

if __name__ == "__main__":
    main()

