#!/usr/bin/env python3
from pwn import *
import itertools

context.log_level = 'error'

def test_flag(flag_content):
    try:
        p = process('/home/ctfplayer/ctf_files/counting')
        p.sendline(flag_content.encode())
        output = p.recvall(timeout=1).decode()
        p.close()
        return output.strip()
    except:
        return ""

def generate_mathematical_sequences():
    sequences = []

    # Test arithmetic sequences based on 0x1a6 (422)
    for step in range(1, 5):
        for start in range(400, 445):
            seq = []
            current = start
            for _ in range(12):
                seq.append(str(current % 10))
                current += step
            sequences.append(''.join(seq))

    # Test sequences based on multiplication by factors
    for base in range(1, 10):
        for factor in [35, 46]:
            seq = []
            current = base
            for _ in range(12):
                seq.append(str(current % 10))
                current = (current * factor) % 100
            sequences.append(''.join(seq))

    # Test direct number values around key constants
    key_values = [422, 0x1a6, 35*46]
    for val in key_values:
        for offset in range(-5, 6):
            num = val + offset
            if len(str(num)) <= 12:
                sequences.append(str(num).zfill(12))

    return sequences

def main():
    print("Testing mathematical sequences...")
    successful_tests = []

    sequences = generate_mathematical_sequences()
    for seq in sequences:
        flag = f"flag{{{seq}}}"
        result = test_flag(flag)

        if result and not result.startswith("Enter"):
            print(f"Potential match found!")
            print(f"Flag: {flag}")
            print(f"Result: {result}")
            print("-" * 40)
            successful_tests.append((flag, result))

            # If we get a promising result, try immediate variations
            base_num = int(seq)
            for offset in [-1, 1, -2, 2]:
                variant = str(base_num + offset).zfill(len(seq))
                variant_flag = f"flag{{{variant}}}"
                variant_result = test_flag(variant_flag)
                if variant_result and not variant_result.startswith("Enter"):
                    successful_tests.append((variant_flag, variant_result))

    print("\nSummary of successful tests:")
    for flag, result in successful_tests:
        print(f"{flag}: {result}")

if __name__ == "__main__":
    main()

